logger = logging.getLogger(__name__)


class FamilyPlannerAttachmentVisionService:
    def __init__(self) -> None:
        self.client = AIClient()
        self.model_name = get_workload_model("vision_high_accuracy")

    def _normalize_text(self, value: Any) -> str:
        return str(value or "").strip()

    def _normalize_string_list(self, value: Any) -> list[str]:
        if not isinstance(value, list):
            return []
        return [
            self._normalize_text(item) for item in value if self._normalize_text(item)
        ]

    def _normalize_key_facts(self, value: Any) -> dict[str, Any]:
        raw_facts = value if isinstance(value, dict) else {}
        return {
            "dates": self._normalize_string_list(raw_facts.get("dates")),
            "times": self._normalize_string_list(raw_facts.get("times")),
            "prices": self._normalize_string_list(raw_facts.get("prices")),
            "location_text": self._normalize_text(raw_facts.get("location_text")),
            "age_guidance": self._normalize_text(raw_facts.get("age_guidance")),
            "rsvp_text": self._normalize_text(raw_facts.get("rsvp_text")),
        }

    def _build_planner_summary(self, normalized_result: dict[str, Any]) -> str:
        summary_parts: list[str] = []
        event_title = self._normalize_text(normalized_result.get("event_title"))
        event_title_visible = bool(normalized_result.get("event_title_visible"))
        key_facts = (
            normalized_result.get("key_facts")
            if isinstance(normalized_result.get("key_facts"), dict)
            else {}
        )

        if event_title_visible and event_title:
            summary_parts.append(f"Visible event title: {event_title}.")
        else:
            summary_parts.append(
                "Uploaded image shows scheduling details but does not explicitly name the event."
            )

        dates = self._normalize_string_list(key_facts.get("dates"))
        if dates:
            summary_parts.append(f"Visible dates: {', '.join(dates[:3])}.")

        times = self._normalize_string_list(key_facts.get("times"))
        if times:
            summary_parts.append(f"Visible times: {', '.join(times[:3])}.")

        prices = self._normalize_string_list(key_facts.get("prices"))
        if prices:
            summary_parts.append(f"Visible prices: {', '.join(prices[:3])}.")

        location_text = self._normalize_text(key_facts.get("location_text"))
        if location_text:
            summary_parts.append(f"Visible location text: {location_text}.")

        age_guidance = self._normalize_text(key_facts.get("age_guidance"))
        if age_guidance:
            summary_parts.append(f"Visible age guidance: {age_guidance}.")

        rsvp_text = self._normalize_text(key_facts.get("rsvp_text"))
        if rsvp_text:
            summary_parts.append(f"Visible RSVP text: {rsvp_text}.")

        visible_text = self._normalize_text(normalized_result.get("visible_text"))
        if (
            not any([dates, times, prices, location_text, age_guidance, rsvp_text])
            and visible_text
        ):
            summary_parts.append("Visible text was captured for follow-up review.")

        observations = self._normalize_string_list(
            normalized_result.get("observations")
        )
        if observations:
            summary_parts.append(observations[0])

        return " ".join(summary_parts)

    def _normalize_attachment_result(self, result: dict[str, Any]) -> dict[str, Any]:
        event_title = self._normalize_text(result.get("event_title"))
        raw_event_title_visible = result.get("event_title_visible")
        event_title_visible = (
            bool(raw_event_title_visible)
            if isinstance(raw_event_title_visible, bool)
            else bool(event_title)
        )
        if not event_title_visible:
            event_title = ""

        visible_text = self._normalize_text(
            result.get("visible_text") or result.get("ocr_text")
        )
        key_facts = self._normalize_key_facts(result.get("key_facts"))
        unknown_fields = self._normalize_string_list(result.get("unknown_fields"))
        if not event_title_visible and "event_title" not in unknown_fields:
            unknown_fields.append("event_title")

        normalized_result = {
            "event_title": event_title,
            "event_title_visible": event_title_visible,
            "visible_text": visible_text,
            "ocr_text": visible_text,
            "key_facts": key_facts,
            "observations": self._normalize_string_list(result.get("observations")),
            "unknown_fields": unknown_fields,
        }
        normalized_result["planner_summary"] = self._build_planner_summary(
            normalized_result
        )
        return normalized_result

    def _build_message_summary(self, results: list[dict[str, Any]]) -> str:
        summaries: list[str] = []
        seen_summaries: set[str] = set()
        for result in results:
            summary = self._normalize_text(result.get("planner_summary"))
            if summary and summary not in seen_summaries:
                seen_summaries.add(summary)
                summaries.append(summary)
        return "\n".join(summaries)

    def _parse_response(self, raw_text: str) -> dict[str, Any]:
        try:
            return json.loads(raw_text)
        except json.JSONDecodeError:
            match = re.search(r"\{.*\}", raw_text, re.DOTALL)
            if not match:
                raise ValueError(
                    "Planner image analysis returned invalid JSON."
                ) from None
            return json.loads(match.group(0))

    def _summarize_existing_attachments(
        self,
        attachments: list[FamilyAgentMessageAttachment],
    ) -> str:
        summaries: list[str] = []
        seen_summaries: set[str] = set()
        for attachment in attachments:
            analysis = attachment.analysis_json or {}
            summary = self._normalize_text(
                analysis.get("message_summary") or analysis.get("planner_summary")
            )
            if not summary and isinstance(analysis, dict):
                summary = self._build_planner_summary(analysis)
            if summary and summary not in seen_summaries:
                seen_summaries.add(summary)
                summaries.append(summary)
        return "\n".join(summaries)

    def analyze_message_attachments(
        self,
        message: FamilyAgentMessage,
    ) -> dict[str, Any]:
        attachments = list(message.attachments.order_by("display_order", "created_at"))
        if not attachments:
            return {
                "message_summary": "",
                "successful_attachments": 0,
                "failed_attachments": 0,
            }

        completed_attachments = [
            attachment
            for attachment in attachments
            if attachment.analysis_status
            == FamilyAgentMessageAttachment.AnalysisStatus.COMPLETED
        ]
        pending_attachments = [
            attachment
            for attachment in attachments
            if attachment.analysis_status
            != FamilyAgentMessageAttachment.AnalysisStatus.COMPLETED
        ]
        if not pending_attachments:
            return {
                "message_summary": self._summarize_existing_attachments(attachments),
                "successful_attachments": len(completed_attachments),
                "failed_attachments": len(attachments) - len(completed_attachments),
            }

        prompt = (
            "You are helping ClanCal's family planner understand uploaded images so later "
            "planning turns can reason about them without re-reading the originals.\n\n"
            "Return strict JSON with this structure:\n"
            "{\n"
            '  "attachments": [\n'
            "    {\n"
            '      "display_order": 0,\n'
            '      "event_title": "Exact visible event or show name, or an empty string when the image never names it.",\n'
            '      "event_title_visible": true,\n'
            '      "visible_text": "Any visible text that matters for planning.",\n'
            '      "key_facts": {\n'
            '        "dates": ["visible date text"],\n'
            '        "times": ["visible time text"],\n'
            '        "prices": ["visible price text"],\n'
            '        "location_text": "visible venue or location text",\n'
            '        "age_guidance": "visible age guidance",\n'
            '        "rsvp_text": "visible RSVP, booking, or approval text"\n'
            "      },\n"
            '      "observations": ["bullet-sized observation"],\n'
            '      "unknown_fields": ["event_title"]\n'
            "    }\n"
            "  ]\n"
            "}\n\n"
            "Focus on dates, times, ages, prices, locations, RSVP details, and event names "
            "that are explicitly visible. "
            "Only include an event or show name when the exact name is visible in the image text. "
            "If the title is missing, say it is unknown instead of guessing. "
            "Do not identify the event from ticketing layouts, venue conventions, date grids, "
            "or prior knowledge. "
            "Be concise and do not invent details that are not visible."
        )

        content: list[dict[str, Any]] = [{"type": "text", "text": prompt}]
        analyzable_attachments: list[FamilyAgentMessageAttachment] = []
        failed_reads = 0

        for attachment in pending_attachments:
            try:
                data_url = PrivateMediaStorageService.read_as_data_url(
                    attachment.object_key,
                    mime_type=attachment.mime_type,
                    storage_alias=attachment.storage_alias,
                )
            except Exception as exc:
                attachment.analysis_status = (
                    FamilyAgentMessageAttachment.AnalysisStatus.FAILED
                )
                attachment.analysis_error_text = str(exc)
                attachment.save(
                    update_fields=[
                        "analysis_status",
                        "analysis_error_text",
                        "updated_at",
                    ]
                )
                failed_reads += 1
                continue

            analyzable_attachments.append(attachment)
            content.extend(
                [
                    {
                        "type": "text",
                        "text": (
                            f"Attachment {attachment.display_order}: "
                            f"{attachment.original_filename}"
                        ),
                    },
                    {
                        "type": "image_url",
                        "image_url": {"url": data_url},
                    },
                ]
            )

        if not analyzable_attachments:
            successful_attachments = FamilyAgentMessageAttachment.objects.filter(
                message=message,
                analysis_status=FamilyAgentMessageAttachment.AnalysisStatus.COMPLETED,
            ).count()
            failed_attachments = FamilyAgentMessageAttachment.objects.filter(
                message=message,
                analysis_status=FamilyAgentMessageAttachment.AnalysisStatus.FAILED,
            ).count()
            return {
                "message_summary": self._summarize_existing_attachments(attachments),
                "successful_attachments": successful_attachments,
                "failed_attachments": failed_attachments,
            }

        try:
            response = self.client.chat.completions.create(
                model=self.model_name,
                messages=[{"role": "user", "content": content}],
                temperature=0.1,
                max_tokens=1400,
                timeout=30,
            )
            parsed = self._parse_response(response.choices[0].message.content or "")
        except Exception as exc:
            error_text = str(exc)
            logger.error(
                "Family planner attachment vision analysis failed: %s",
                exc,
                exc_info=True,
            )
            FamilyAgentMessageAttachment.objects.filter(
                id__in=[attachment.id for attachment in analyzable_attachments]
            ).update(
                analysis_status=FamilyAgentMessageAttachment.AnalysisStatus.FAILED,
                analysis_error_text=error_text,
            )
            return {
                "success": False,
                "error": error_text,
                "message_summary": "",
                "successful_attachments": len(completed_attachments),
                "failed_attachments": len(analyzable_attachments) + failed_reads,
            }

        raw_results = parsed.get("attachments")
        attachment_results = (
            [item for item in raw_results if isinstance(item, dict)]
            if isinstance(raw_results, list)
            else []
        )
        results_by_order = {
            int(result["display_order"]): self._normalize_attachment_result(result)
            for result in attachment_results
            if str(result.get("display_order", "")).strip().isdigit()
        }
        message_summary = self._build_message_summary(list(results_by_order.values()))

        with transaction.atomic():
            for attachment in analyzable_attachments:
                result = results_by_order.get(attachment.display_order)
                if result is None:
                    attachment.analysis_status = (
                        FamilyAgentMessageAttachment.AnalysisStatus.FAILED
                    )
                    attachment.analysis_error_text = (
                        "Planner image analysis did not return a result for this image."
                    )
                    attachment.save(
                        update_fields=[
                            "analysis_status",
                            "analysis_error_text",
                            "updated_at",
                        ]
                    )
                    continue

                attachment.analysis_status = (
                    FamilyAgentMessageAttachment.AnalysisStatus.COMPLETED
                )
                attachment.analysis_error_text = ""
                attachment.analysis_json = {
                    **result,
                    "message_summary": message_summary,
                }
                attachment.save(
                    update_fields=[
                        "analysis_status",
                        "analysis_error_text",
                        "analysis_json",
                        "updated_at",
                    ]
                )

        successful_attachments = FamilyAgentMessageAttachment.objects.filter(
            message=message,
            analysis_status=FamilyAgentMessageAttachment.AnalysisStatus.COMPLETED,
        ).count()
        failed_attachments = FamilyAgentMessageAttachment.objects.filter(
            message=message,
            analysis_status=FamilyAgentMessageAttachment.AnalysisStatus.FAILED,
        ).count()

        return {
            "message_summary": message_summary
            or self._summarize_existing_attachments(
                list(message.attachments.order_by("display_order", "created_at"))
            ),
            "successful_attachments": successful_attachments,
            "failed_attachments": failed_attachments,
        }
